//! Differential tests against the C++ PR_ParseTimeString.
//!
//! The table below was produced by compiling the unmodified
//! base/third_party/nspr/prtime.cc with g++ and running it on the inputs
//! listed here. The C++ side ran with TZ=UTC for zone offset 0 and with
//! TZ=PST+8 (a fixed UTC-8 offset with no DST) for offset -28800. The Rust
//! side uses the same offsets through `parse_time_string_with_local_offset`.
//! Each row is (hex input, default_to_gmt, local offset in seconds, ok,
//! result). Inputs are hex-encoded so that NUL and high bytes are kept exactly.

use prtime::{parse_time_string_with_local_offset, PrTime};

fn decode_hex(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex"))
        .collect()
}

