#[test]
fn matches_cpp_reference_outputs() {
    for &(hex, default_to_gmt, zone_offset, ok, result) in CASES {
        let input = decode_hex(hex);
        let got = parse_time_string_with_local_offset(&input, default_to_gmt, &move |_| zone_offset);
        let want = if ok { Some(result) } else { None };
        assert_eq!(
            got, want,
            "input {:?} default_to_gmt={} offset={}",
            String::from_utf8_lossy(&input),
            default_to_gmt,
            zone_offset
        );
    }
    assert!(CASES.iter().filter(|c| c.3).count() > 150);
}
